function listDirtyEntries() {
  const raw = execSync("git status --porcelain=v1 --untracked-files=all", {
    cwd: root,
    stdio: ["ignore", "pipe", "pipe"]
  }).toString("utf8");

  // Never `.trim()` the whole stdout: the first column is often a leading space
  // (index clean, worktree modified). Trimming would turn ` M path` into `M path`
  // and break `parseStatusLine`.
  return raw
    .split(/\r?\n/)
    .map((line) => line.replace(/\r$/, "").trimEnd())
    .filter((line) => line.length > 0)
    .map((line) => parseStatusLine(line))
    .filter((entry) => entry && entry.path);
}

