function runRendererBuild(repoRoot) {
  const rendererRoot = path.join(repoRoot, 'src', 'renderer');
  // Run from renderer root so npm puts `node_modules/.bin` on PATH (Windows CI
  // was failing on `vite build` when invoked via `npm --prefix ...` from repo root).
  const result = spawnSync('npm run build', {
    cwd: rendererRoot,
    stdio: 'inherit',
    shell: true,
  });

  if (result.error) {
    console.error('[renderer:ensure-build] Failed to start renderer build:', result.error.message);
    process.exit(1);
  }

  if (result.status !== 0) {
    process.exit(result.status || 1);
  }
}

