function safeArithmeticEval(raw) {
    const s = String(raw).replace(/\s/g, '');
    if (!s || !/^[\d.+\-*/()]+$/.test(s)) throw new Error('Only digits and + - * / ( ) .');
    let i = 0;
    const peek = () => s[i];
    const eat = (c) => {
        if (peek() !== c) throw new Error('Invalid expression');
        i += 1;
    };
    const parseNumber = () => {
        const start = i;
        while (i < s.length && /[\d.]/.test(peek())) i += 1;
        if (start === i) throw new Error('Expected number');
        const n = Number(s.slice(start, i));
        if (!Number.isFinite(n)) throw new Error('Invalid number');
        return n;
    };
    const parseFactor = () => {
        if (peek() === '(') {
            eat('(');
            const v = parseExpr();
            eat(')');
            return v;
        }
        return parseNumber();
    };
