/** Reject floating semver tags on third-party actions; allow 40-char SHAs and the SLSA reusable workflow pin. */
function assertWorkflowUsesArePinnedToSha() {
  const names = fs.readdirSync(workflowsDir).filter((n) => n.endsWith(".yml") || n.endsWith(".yaml"));
  for (const name of names) {
    const text = readFile(path.join(workflowsDir, name));
    const lines = text.split("\n");
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmed = line.trimStart();
      if (!trimmed.startsWith("uses:")) continue;
      if (trimmed.includes("${{")) continue;
      const m = trimmed.match(/^uses:\s*(.+)$/);
      if (!m) continue;
      const spec = m[1].replace(/\s+#.*$/, "").trim();
      if (!spec.includes("@")) continue;
      const ref = spec.split("@").pop();
      if (/^[0-9a-f]{40}$/i.test(ref)) continue;
      assert(
        spec.includes(SLSA_REUSABLE_PREFIX),
        `${name}:${i + 1} must pin GitHub Actions to a 40-char commit SHA (got ref "${ref}" in "${spec}"). ` +
          "Exception: slsa-framework reusable workflow semver pin only."
      );
    }
  }
}

