async function railWidth(testId) {
    const el = page.getByTestId(testId);
    await el.scrollIntoViewIfNeeded().catch(() => {});
    try {
        const box = await el.boundingBox({ timeout: 8000 });
        if (box && Number.isFinite(box.width) && box.width > 0) return box.width;
    } catch {
        /* layout stability wait can flake after rail toggles — fall back to DOM geometry */
    }
    return page.evaluate((id) => {
        const node = document.querySelector(`[data-testid="${id}"]`);
        if (!node) return 0;
        const r = node.getBoundingClientRect();
        return Number.isFinite(r.width) ? r.width : 0;
    }, testId);
}

